gVQ(){return"\u0628\u06c6 \u0647\u06cc\u0686 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u06a9 \u062f\u0627\u0646\u06d5\u0646\u0631\u0627\u0648\u06d5"},
gVR(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u062c\u06c6\u0631\u06ce\u06a9\u06cc \u062a\u06ce\u0686\u0648\u0648 \u0646\u06cc\u06cc\u06d5 \u2014 \u0633\u06d5\u0631\u06d5\u062a\u0627 \u06cc\u06d5\u06a9\u06ce\u06a9 \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5."},
