gXv(){return"\u067e\u0632\u06cc\u0634\u06a9\u06d5 \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646"},
gXw(){return"\u0626\u06d5\u0645 \u0633\u06a9\u0631\u062a\u06ce\u0631\u06d5 \u0628\u06d5\u0631\u067e\u0631\u0633\u06cc\u0627\u0631\u06d5 \u0644\u06d5 \u06a9\u0627\u0645 \u067e\u0632\u06cc\u0634\u06a9(\u06d5\u06a9\u0627\u0646). \u0647\u06d5\u0645\u0648\u0648 \u0647\u06d5\u06b5\u0645\u06d5\u0628\u0698\u06ce\u0631\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06cc\u0686 \u0633\u0646\u0648\u0648\u0631\u06ce\u06a9 \u0646\u06d5\u0628\u06ce\u062a (\u0647\u06d5\u0645\u0648\u0648 \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a)."},
guN(){return"\u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06d5 \u0695\u06ce\u067e\u06ce\u062f\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646"},
guO(){return"\u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u06a9\u0627\u0645 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06d5\u06a9\u0627\u0646 \u0626\u06d5\u0646\u062c\u0627\u0645 \u062f\u06d5\u062f\u0627\u062a. \u0647\u06d5\u0645\u0648\u0648 \u0647\u06d5\u06b5\u0645\u06d5\u0628\u0698\u06ce\u0631\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06cc\u0686 \u0633\u0646\u0648\u0648\u0631\u06ce\u06a9 \u0646\u06d5\u0628\u06ce\u062a (\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0647\u06d5\u0645\u0648\u0648 \u0634\u062a\u06ce\u06a9\u06cc \u06a9\u06d5\u062a\u0627\u0644\u06c6\u06af\u06d5\u06a9\u06d5 \u0626\u06d5\u0646\u062c\u0627\u0645 \u0628\u062f\u0627\u062a)."},
gXM(){return"\u0695\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06d5\u06a9\u0627\u0646"},
gXN(){return"\u0695\u0627\u06cc\u0628\u06a9\u06ce\u0634\u06d5 \u0628\u06c6 \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0695\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc \u062f\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0646\u06cc \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5. \u0628\u06d5\u0628\u06ce \u0695\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc\u060c \u0695\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc \u06a9\u06d5\u062a\u0627\u0644\u06c6\u06af\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0628\u06d5\u06a9\u0627\u0631\u062f\u06ce\u062a."},
gXO(){return"\u0695\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5"},
gXF(){return"\u0646\u0627\u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646 \u2014 \u0626\u06d5\u0645 \u06a9\u06d5\u0633\u06d5 \u0646\u0627\u062a\u0648\u0627\u0646\u06ce\u062a \u0628\u0686\u06ce\u062a\u06d5 \u0698\u0648\u0648\u0631\u06d5\u0648\u06d5"},
gXP(){return"\u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5"},
gXy(){return"\u0646\u0627\u062a\u0648\u0627\u0646\u06cc\u062a \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u062e\u06c6\u062a \u0646\u0627\u0686\u0627\u0644\u0627\u06a9 \u0628\u06a9\u06d5\u06cc\u062a"},
gXx(){return"\u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u062a\u0627\u06a9\u06d5 \u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631\u06cc \u0686\u0627\u0644\u0627\u06a9 \u0646\u0627\u0686\u0627\u0644\u0627\u06a9 \u0628\u06a9\u0631\u06ce\u062a"},
gXJ(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644 \u0648 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u067e\u06ce\u0648\u06cc\u0633\u062a\u0646"},
