gXQ(){return"\u062f\u0648\u0648\u067e\u0627\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gXT(){return"\u0648\u0634\u06d5 \u0646\u0647\u06ce\u0646\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0648\u06d5\u06a9 \u06cc\u06d5\u06a9 \u0646\u06cc\u0646"},
gXW(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u062f\u06d5\u0628\u06ce\u062a \u0644\u0627\u0646\u06cc\u06a9\u06d5\u0645 \u0666 \u067e\u06cc\u062a \u0628\u06ce\u062a"},
XV(a){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u06af\u06c6\u0695\u062f\u0631\u0627. \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5\u06af\u06d5\u06b5 "+a+" \u0647\u0627\u0648\u0628\u06d5\u0634 \u0628\u06a9\u06d5."},
Gr(a){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
